def f2(g):
    H,W=len(g),len(g[0])
    cc=collections.defaultdict(list)
    for i in range(H):
        for j in range(W):
            if g[i][j]: cc[g[i][j]].append((i,j))
    big=max(cc,key=lambda v:len(cc[v]))
    cells=cc[big]
    if len(set(a for a,b in cells))==1:
        kf=lambda i,j:i
    elif len(set(a+b for a,b in cells))==1:
        kf=lambda i,j:a+b
    elif len(set(a-b for a,b in cells))==1:
        kf=lambda i,j:a-b
    else:
        # dominant run direction among all colors
        tot={('H',0):0,('V',0):0,('AD',0):0,('D',0):0}
        for v,cs_ in cc.items():
            for a,b in cs_:
                if a+1<len(g) and g[a+1][b]==v: tot[('H',0)]+=1
                if b+1<W and g[a][b+1]==v: tot[('V',0)]+=1
                if a+1<len(g) and b-1>=0 and g[a+1][b-1]==v: tot[('AD',0)]+=1
                if a+1<len(g) and b+1<W and g[a+1][b+1]==v: tot[('D',0)]+=1
        name,tot_=max(tot.items(), key=lambda x:x[1])
        if name=='H': kf=lambda i,j:i
        elif name=='V': kf=lambda i,j:j
        elif name=='AD': kf=lambda i,j:i+j
        else: kf=lambda i,j:i-j
    n=len(set(kf(a,b) for a,b in cells))
    # sequence of colors in order of increasing key
    seq=[None]*n
    items=sorted([(kf(a,b),v) for v,cs_ in cc.items() for a,b in cs_])
    idx=set()
    for k,v in items:
        if k not in idx: seq[(k-min(x for x,_ in items))%n]=v; idx.add(k)
    return [[seq[(kf(a,b))%n] for b in range(W)] for a in range(H)]

